mapper.insert:
/* addRegionInfo */
INSERT INTO REGION_INFO (
    REGN_CD
    , REGN_NM
    , SIGNGU_CD
    , SIGNGU_NM
) 
VALUES (
    #{regnCd}
    , #{regnNm}
    , #{signguCd}
    , #{signguNm}
)

/* addClassificationInfo */
INSERT INTO CLASSIFICATION_CODE (
    lclsSystm1Cd
    , lclsSystm1Nm
    , lclsSystm2Cd
    , lclsSystm2Nm
    , lclsSystm3Cd
    , lclsSystm3Nm
)
VALUES (
    #{lclsSystm1Cd}
    , #{lclsSystm1Nm}
    , #{lclsSystm2Cd}
    , #{lclsSystm2Nm}
    , #{lclsSystm3Cd}
    , #{lclsSystm3Nm}
)
ON DUPLICATE KEY UPDATE
    lclsSystm1Nm = #{lclsSystm1Nm}
    , lclsSystm2Nm = #{lclsSystm2Nm}
    , lclsSystm3Nm = #{lclsSystm3Nm}
    , updated_at = CURRENT_TIMESTAMP

mapper.select:
/* loadRegionId */
SELECT RI.REGN_ID
FROM REGION_INFO RI





                    AND RI.REGN_NM = #{region}


                    AND RI.REGN_CD = #{region}




            AND RI.REGN_CD = #{region}






                    AND RI.SIGNGU_NM = #{sigungu}


                    AND RI.SIGNGU_CD = #{sigungu}




            AND RI.SIGNGU_CD = #{sigungu}
